// spec: .qa/e2e/specs/history.md (4.1)
// seed: tests/seed.user.spec.ts
// @data: создаёт 1 завершённый сеанс мониторинга (удалить нельзя). Запускать по одному.
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, slide } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(120_000);

const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();

test.describe('История — новый сеанс', () => {
  test('Завершённый сеанс без событий сохраняется и первым появляется в «היסטוריה» и в «ניטורים אחרונים» #78e3149c @iphone @data', async ({ page }) => {
    // 1. Мониторинг без событий (мок calm — только веб: ?mock в адресе)
    await startMonitoring(page, 'calm');

    // 2. «כבה את המצלמה» → сводка
    await slide(page, 'כבה את המצלמה');
    await page.waitForURL(/\/monitor\/summary/, { timeout: 15_000 });

    // 3. Время начала из интервала HH:MM–HH:MM
    const interval = page.getByText(/\d{1,2}:\d{2}\s*[–-]\s*\d{1,2}:\d{2}/).filter({ visible: true }).first();
    await expect(interval).toBeVisible();
    const start = /(\d{1,2}:\d{2})/.exec(clean((await interval.textContent()) ?? ''))![1];

    // 4. «לכל הניטורים» → /history: первая запись в группе «היום»
    await page.getByRole('button', { name: 'לכל הניטורים' }).filter({ visible: true }).click();
    await page.waitForURL(/\/history/);
    const firstGroup = page.getByRole('heading', { name: /^(היום|אתמול|\d{1,2}\.\d{1,2})$/ }).filter({ visible: true }).first();
    await expect(firstGroup).toHaveText('היום');
    const first = page.getByRole('button', { name: /ניטור, / }).filter({ visible: true }).first();
    await expect(first).toContainText(start);
    const histText = clean(await first.innerText());
    expect(histText).toMatch(/\d+\s*(דק׳|שע׳|שנ׳)/);
    expect(histText).toMatch(/בלי אירועים$/);

    // 5. Таб «בית» → «ניטורים אחרונים»: первая строка
    await page.getByRole('tab', { name: 'בית' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/home/);
    await expect(page.getByRole('heading', { name: 'ניטורים אחרונים' }).filter({ visible: true })).toBeVisible();
    const recent = page.getByRole('button', { name: /דק׳ · / }).filter({ visible: true }).first();
    await expect(recent).toContainText(start);
    const homeText = clean(await recent.innerText());
    expect(homeText).toMatch(new RegExp(`^היום, ${start}`));
    expect(homeText).toMatch(/בלי אירועים$/);
  });
});
